// 字符串转换整数 (atoi)
public class StringToIntegerAtoi {

    public int myAtoi(String s) {
        if (s == null || s.length() == 0) return 0;

        int index = 0;
        int n = s.length();

        // 1. 跳过前导空格
        while (index < n && s.charAt(index) == ' ') {
            index++;
        }

        // 字符串全是空格
        if (index == n) return 0;

        // 2. 处理符号
        int sign = 1;
        if (s.charAt(index) == '+' || s.charAt(index) == '-') {
            sign = s.charAt(index) == '-' ? -1 : 1;
            index++;
        }

        // 3. 逐字符转换数字
        int result = 0;
        while (index < n) {
            char c = s.charAt(index);

            // 非数字字符，终止
            if (c < '0' || c > '9') {
                break;
            }

            int digit = c - '0';

            // 4. 溢出检查：在累加前检查
            if (result > (Integer.MAX_VALUE - digit) / 10) {
                return sign == 1 ? Integer.MAX_VALUE : Integer.MIN_VALUE;
            }

            result = result * 10 + digit;
            index++;
        }

        return sign * result;
    }

    // 测试
    public static void main(String[] args) {
        StringToIntegerAtoi solution = new StringToIntegerAtoi();
        System.out.println(solution.myAtoi("42"));           // 42
        System.out.println(solution.myAtoi("   -42"));      // -42
        System.out.println(solution.myAtoi("4193 with words")); // 4193
        System.out.println(solution.myAtoi("words and 987"));   // 0
        System.out.println(solution.myAtoi("-91283472332"));     // -2147483648 (INT_MIN)
    }
}
